+import { daysLeft, isExpired } from "./expiry.js";
+
+/** Builds a shelf report at the given time. */
+export function buildReport(items, now) {
+  const active = [];
+  const expired = [];
+  const tags = new Map();
+  let units = 0;
+
+  for (const item of items) {
+    if (isExpired(item, now)) {
+      expired.push(item.name);
+      continue;
+    }
+    active.push(item);
+    units += item.qty;
+    for (const tag of new Set(item.tags)) {
+      tags.set(tag, (tags.get(tag) || 0) + 1);
+    }
+  }
+
+  return {
+    generatedAt: new Date(now).toISOString(),
+    total: active.length,
+    units,
+    byTag: Object.fromEntries([...tags].sort(([a], [b]) => a.localeCompare(b))),
+    expiringSoon: active
+      .filter((item) => daysLeft(item, now) <= 3)
+      .sort((a, b) => Date.parse(a.expires) - Date.parse(b.expires) || a.name.localeCompare(b.name))
+      .map((item) => item.name),
+    expired: expired.sort((a, b) => a.localeCompare(b)),
+  };
+}
